SELECT * FROM kb_document WHERE category_id = #{categoryId} AND title = #{title}
AND tenant_id = #{tenantId}
LIMIT 1

SELECT * FROM kb_document WHERE category_id = #{categoryId}
AND tenant_id = #{tenantId}
ORDER BY update_time DESC
LIMIT #{pageSize} OFFSET (#{page} - 1) * #{pageSize}

SELECT * FROM kb_document
WHERE (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
AND tenant_id = #{tenantId}
ORDER BY update_time DESC
LIMIT #{pageSize} OFFSET (#{page} - 1) * #{pageSize}

SELECT COUNT(*) FROM kb_document
WHERE (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
AND tenant_id = #{tenantId}

mapper.update:
UPDATE kb_document SET category_id = #{categoryId}, title = #{title}, summary = #{summary},
    content = #{content}, content_size = #{contentSize}, last_editor_id = #{lastEditorId},
    version_no = #{versionNo}, status = #{status}, update_time = #{updateTime}
WHERE id = #{id} AND tenant_id = #{tenantId}
